#!/usr/bin/env python3
# Uso: python3 -I -B ct_gen_informe_pruebas.py <dir_cierre>. Genera INFORME_PRUEBAS_FINALES.md a partir de resultados/bateria_final/ (INDICE y ENTORNO): nada se escribe a mano desde memoria.
import csv, os, sys
c = sys.argv[1]; B = os.path.join(c, "scripts_validacion", "resultados", "bateria_final")
idx = list(csv.DictReader(open(os.path.join(B, "INDICE_BATERIA.csv"), encoding="utf-8"))); env = open(os.path.join(B, "ENTORNO.txt"), encoding="utf-8").read().strip().splitlines()
NAT = {"v20_pe": "LOCAL fixture V20", "v20_mutaciones": "LOCAL fixture V20", "extension_local": "LOCAL prototipos", "concurrencia_local": "LOCAL (2 sesiones)", "dg19": "LOCAL experimento", "hash_encadenado": "LOCAL (pgcrypto)",
 "estatica_T47_T124": "ESTÁTICA (textos)", "k47_por_escenario": "MODELO en memoria", "t409_individual": "MODELO en memoria", "t409_repro_2a_corrida": "MODELO en memoria (reproducibilidad)", "t409_repro_comparacion": "comparación byte a byte",
 "t409_correspondencia": "análisis de correspondencia (inferido)", "funciones_22": "MODELO en memoria", "exc_modelo14": "MODELO en memoria", "catalogo_except": "AST + ejecución en memoria", "arnes_r1r9": "LOCAL: prueba el ARNÉS (stubs), no R1–R9",
 "smoke_6_scripts": "LOCAL shim/fixtures; no es Supabase (el veredicto está en aserciones_smoke)", "aserciones_smoke": "aserciones de CONTENIDO sobre las salidas del smoke", "escaner_sql": "ESTÁTICA heurística", "escaner_texto": "ESTÁTICA heurística", "escaner_autoprueba": "control negativo del escáner"}
L = ["# INFORME DE PRUEBAS FINALES (locales) — generado desde `resultados/bateria_final/`", "",
 "**Etiqueta:** todos los resultados son de PostgreSQL 16 temporal local, modelo en memoria o análisis estático. **Ninguno valida el esquema físico de CCI-DEV** ni toca Supabase/CCI-PROD. Las salidas anteriores se borraron antes de ejecutar (ninguna se reutiliza); cada fila tiene fecha, comando, resultado y SHA-256 de la salida.", "", "## Entorno", "", "```"] + env + ["```", "",
 "## Resultados de la batería", "", "| Paso | Naturaleza | Inicio UTC | Fin UTC | Inicio local (zona) | Fin local | rc | Estado (rc=0 y contenido esperado) | Contenido esperado | Resultado | Salida | SHA-256 (16) |", "|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in idx: L.append("| %s | %s | %s | %s | %s %s | %s | %s | %s | `%s` | %s | `%s` | %s |" % (r["paso"], NAT.get(r["paso"], ""), r["inicio_utc"], r["fin_utc"], r["inicio_local"], r["zona_local"], r["fin_local"], r["rc"], r["estado"], r["esperado"].replace("|", "/"), r["resumen"].replace("|", "/"), r["salida"], r["sha256_salida"][:16]))
L += ["", "Las horas tienen UTC (sufijo Z) y local con desfase; ver `INFORME_AUDITORIA_FECHAS_HORAS.md`. Comandos exactos: columna `comando` de `scripts_validacion/resultados/bateria_final/INDICE_BATERIA.csv`. Los pasos `smoke_6_scripts` y los controles negativos del manifiesto (`resultados/controles_negativos_manifiesto.txt`) se verifican además en `INFORME_RECONCILIACION_INTEGRAL.md`.", "",
 "## Historial de fallos y correcciones (no se omiten)",
 "Ronda anterior: (1) clúster sin `-k/-p`; (2) `\\if … \\else … \\endif` en una línea; (3) adaptador de 22 funciones leía `(nombre, [])` como falso; (4) comparación `e in c` en T-409..T-422 (confundía I1 con I10/I11/I12) → igualdad exacta; (5) 04 v1 con 11 falsos PASS → v2; (6) 03 v1 con columna inexistente y sondas DELETE/TRUNCATE; (7) shim RLS no versionado; (8) 4 falsos positivos del escáner v1.",
 "Esta ronda: (9) el verificador de manifiesto v1 omitía en silencio enlaces simbólicos, comparaba contra una lista permitida de «extras» sin separar la evidencia y no probaba la vía B → `ct_manifiesto.py` (36 controles negativos, incluida la vía B con `gh` simulado); (10) el HEAD final no podía contener la evidencia de su propia verificación → diseño de punto fijo (evidencia en `evidencia_verificacion/`, excluida y verificada con `--base`); (11) el contrato de error de 04 comparaba por prefijo de texto (aceptaría `RJ00` como `RJ003`) → SQLSTATE exacto (casos C23–C25); (12) el contrato de la autoprueba y el del plan eran distintos → propuesta única (`PROPUESTA_CONTRATO_ERRORES_R1_R9.md`); (13) el escáner v1 no analizaba el interior de `$$…$$` → corregido, con muestras; (14) falsos positivos del escáner v2 (palabra `EXECUTE` dentro de literales; teléfonos en UUID; muestras autocontenidas) → ajustados y probados; (15) ejecución previa con argumentos erróneos de script (sin efecto en datos).",
 "Ronda final: (16) el informe de reconciliación se generó desde una ejecución anterior (FAIL=1) y el TXT se reescribió después (FAIL=0) → una sola ejecución JSON→TXT+MD + verificador de consistencia con controles negativos; (17) la batería aceptaba rc=0 sin comprobar el contenido → columna «esperado» y estado por paso (detectó que el total del escáner de texto depende del árbol: 571→631→701; el total se genera, no se copia); (18) el smoke de los 6 scripts no tenía veredicto propio → `ct_aserciones_smoke.py` (11 aserciones de contenido originales; la remediación H-01 añadió la precondición de roles); (19) rutas absolutas del entorno en el índice → rutas relativas; (20) el verificador de referencias aceptaba coincidencias por nombre base en cualquier carpeta y leía el informe generado → ruta exacta, enlaces relativos y exclusión del informe generado; (21) cifras obsoletas «64/0» (LEEME, dictamen) y «28 limitaciones» → cifras generadas desde los resultados; (22) la batería registraba como `HEAD_local` un commit anterior al árbol ejecutado → ahora registra el commit base, los archivos con cambios y un digest de las entradas.\nHistóricos heredados que se conservan: RV07 corrida 1 FAIL; SQL_ASCII 77/80 (DEF-ENV-01); corridas 1/2 del shim.", "",
 "Remediación de la auditoría independiente: (H-01) el smoke 02 dependía de los roles `anon`/`authenticated`/`service_role`, que solo existían si una ejecución anterior los había dejado en el clúster → la batería los crea y verifica explícitamente antes del smoke (sin login ni superusuario) y se añadió la aserción de precondición; reproducido en dos clústeres nuevos; (H-02) las etiquetas de la reconciliación llevaban cifras escritas a mano (21/21, 11/11, 21 pasos) que quedaron obsoletas frente a las pruebas reales (28/28, 12 aserciones) → las etiquetas se componen desde los resultados y el recuento de pasos se compara con los pasos declarados en la batería; (H-03) la guarda DEV/PROD solo confiaba en variables declaradas → guarda compartida por identidad efectiva (system_identifier + base + roles de plataforma) con allowlist/denylist literales, falla cerrada y pruebas negativas sobre los 6 scripts (paso `guarda_destino`).",
 "## Qué NO prueban", "No prueban el esquema físico, RLS, privilegios, R1–R9 reales, concurrencia real ni comportamiento de Supabase. Todo PASS aquí es PASS_LOCAL / PASS_PROTOTYPE / PASS_STATIC / PASS_MODEL; **PASS_PHYSICAL = 0**. Ausencia de fallos no demuestra corrección: demuestra que las pruebas existentes no encuentran fallos."]
open(os.path.join(c, "INFORME_PRUEBAS_FINALES.md"), "w", encoding="utf-8").write("\n".join(L) + "\n"); print("ok", len(idx))
